import numpy as np, heapq, math
from PIL import Image
A=np.array(Image.open('/app/target.png').convert('L'))<180
A=A[495:570,350:665].copy();im=A.copy()
while True:
 changed=0
 for step in (0,1):
  p=np.pad(im,1)
  n=p[:-2,1:-1]; ne=p[:-2,2:]; e=p[1:-1,2:]; se=p[2:,2:]; s=p[2:,1:-1]; sw=p[2:,:-2]; w=p[1:-1,:-2]; nw=p[:-2,:-2]
  ns=[n,ne,e,se,s,sw,w,nw]; count=sum(x.astype(np.uint8) for x in ns); trans=sum((~ns[i] & ns[(i+1)%8]).astype(np.uint8) for i in range(8))
  cond=im&(count>=2)&(count<=6)&(trans==1)
  if step==0:cond &=~(n&e&s)&~(e&s&w)
  else:cond &=~(n&e&w)&~(n&s&w)
  changed+=int(cond.sum()); im[cond]=0
 if changed==0:break
Y,X=np.where(im); sk={(int(y+495),int(x+350)) for y,x in zip(Y,X)}
# nearest skeleton pixel

def near(p):
 x,y=p; return min(sk,key=lambda q:(q[1]-x)**2+(q[0]-y)**2)
def path(a,b):
 a=near(a);b=near(b); q=[(0,a)]; ds={a:0}; prev={}
 while q:
  d,p=heapq.heappop(q)
  if d!=ds[p]:continue
  if p==b:break
  y,x=p
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if dx==dy==0:continue
    n=(y+dy,x+dx)
    if n not in sk:continue
    # all 8 edges
    nd=d+math.hypot(dx,dy)
    if nd<ds.get(n,1e9):ds[n]=nd;prev[n]=p;heapq.heappush(q,(nd,n))
 p=b; out=[p]
 while p!=a:p=prev[p];out.append(p)
 out=out[::-1]
 # resample every ~5 path px
 acc=0; samples=[out[0]]
 for old,new in zip(out,out[1:]):
  acc+=math.dist(old,new)
  if acc>=5:samples.append(new);acc=0
 if samples[-1]!=out[-1]:samples.append(out[-1])
 return a,b,round(ds[b],1),[(x,y) for y,x in samples]
land=[(360,532),(398,507),(368,554),(420,508),(412,552),(496,507),(470,553),(533,507),(508,551),(595,507),(565,553),(615,508),(607,550),(653,532)]
for a,b in zip(land,land[1:]):
 p0,p1,d,pts=path(a,b);print(f'{a}->{b}: actual {p0}->{p1}, dist {d}: {pts}')
# degrees with all-neigh

def neigh(p):
 y,x=p;return [(y+dy,x+dx) for dy in (-1,0,1) for dx in (-1,0,1) if (dx or dy) and (y+dy,x+dx) in sk]
from collections import Counter
print('sk',len(sk),'degree',Counter(len(neigh(p)) for p in sk))
